  const limit = 10 ** String(n).length;
  const isPrime = new Array(limit).fill(true);
  isPrime[0] = isPrime[1] = false;
  for (let p = 2; p * p < limit; p++) {
    if (!isPrime[p]) continue;
    for (let q = p * p; q < limit; q += p) isPrime[q] = false;
  }
  if (isPrime[n] || isPrime[m]) return -1;

  // A min-heap of [cost, value] pairs, ordered by cost.
  const heap = [];
  function push(item) {
    heap.push(item);
    let i = heap.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (heap[parent][0] <= heap[i][0]) break;
      [heap[parent], heap[i]] = [heap[i], heap[parent]];
      i = parent;
    }
  }
  function pop() {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length === 0) return top;
    heap[0] = last;
    let i = 0;
    while (2 * i + 1 < heap.length) {
      let child = 2 * i + 1;
      if (child + 1 < heap.length && heap[child + 1][0] < heap[child][0]) child++;
      if (heap[i][0] <= heap[child][0]) break;
      [heap[i], heap[child]] = [heap[child], heap[i]];
      i = child;
    }
    return top;
  }

  const best = new Array(limit).fill(Infinity);
  function relax(cost, next) {
    if (isPrime[next] || cost + next >= best[next]) return;
    best[next] = cost + next;
    push([best[next], next]);
  }

  best[n] = n;
  push([n, n]);
