function minOperations(n, m) {
  const isPrime = x => {
    if (x < 2) return false;
    for (let d = 2; d * d <= x; d++) if (x % d === 0) return false;
    return true;
  };
  if (isPrime(n) || isPrime(m)) return -1;
  const width = String(n).length;
  // Bellman-Ford style: keep improving every reachable value's cost until nothing changes.
  const best = new Map([[n, n]]);
  let changed = true;
  while (changed) {
    changed = false;
    for (const [value, cost] of [...best]) {
      const digits = String(value);
      for (let i = 0; i < digits.length; i++) {
        for (const step of [1, -1]) {
          const digit = Number(digits[i]) + step;
          if (digit < 0 || digit > 9) continue;
          const next = Number(digits.slice(0, i) + digit + digits.slice(i + 1));
          if (String(next).length !== width || isPrime(next)) continue;
          if (!best.has(next) || cost + next < best.get(next)) {
            best.set(next, cost + next);
            changed = true;
          }
        }
      }
    }
  }
  return best.has(m) ? best.get(m) : -1;
}

