function generate(rand, size) {
  const width = size === 'large' ? 4 : 1 + Math.floor(rand() * 3);
  const low = width === 1 ? 1 : 10 ** (width - 1), high = 10 ** width - 1;
  const pick = () => low + Math.floor(rand() * (high - low + 1));
  const prime = x => { if (x < 2) return false; for (let d = 2; d * d <= x; d++) if (x % d === 0) return false; return true; };
  // Mostly non-prime values, so that a route usually exists; sometimes anything, which may be prime.
  const choose = () => { if (rand() < 0.2) return pick(); for (;;) { const x = pick(); if (!prime(x)) return x; } };
  const n = choose();
  const m = rand() < 0.1 ? n : choose();
  return [n, m];
}
